/**
 * Git surface, browser half: the right Sidebar's **Source control** tab and the
 * frame's rail button that opens it.
 *
 * The panel reads one Workspace's repository through the generated `git` Remote
 * namespace. Its state model lives for exactly as long as the plugin fiber.
 */
import type { Context as ClientContext } from '@deepseek-ai/cordis'
import type { ClientRemote, WorkspaceId } from '@deepseek-ai/dsh-api-remotes/client'
import gitRemote from '@deepseek-ai/dsh-git-panel/remote'
import type {} from '@deepseek-ai/dsh-api-workspace-controller/client'
import type {} from '@deepseek-ai/dsh-client-locale/client'
import type {} from '@deepseek-ai/dsh-client-ui-renderer/client'
import type {} from '@deepseek-ai/dsh-client-ui-sidebar-right/client'
import type {} from '@deepseek-ai/dsh-client-ui-editor/client'
import { fileAddressFor } from '@deepseek-ai/dsh-util-workspace-path'
import { GitPanel } from './GitPanel.tsx'
import { GitTitle } from './GitTitle.tsx'
import { GitRailIcon } from './GitRailIcon.tsx'
import { GIT_ID, GIT_KIND, gitDefinition } from './definition.tsx'
import { createChangeCountSource, type ChangeCountSource } from './change-count.ts'
import { createGitLive, type GitLive } from './live.ts'
import { GitPanelModel } from './model.ts'
import { en, zh, type GitLocaleKey } from './locales.ts'
import type { GitWatchFrame } from '@deepseek-ai/dsh-git-panel/types'
import type { GitPanelInjected } from './slots.ts'
import type { GitRailInjected } from './GitRailIcon.tsx'

declare module '@deepseek-ai/dsh-client-ui-slots' {
  interface LocaleNamespaceMap {
    /** Git panel copy. */
    git: GitLocaleKey
  }
}

/** Dictionary namespace owned by this plugin. */
export const NS = 'git'

/** Required services: the slots, dictionaries, right Sidebar and its tab registry, Workspace rows, and the `git` namespace. */
export const inject = ['slots', 'locale', 'workspaces', 'sidebarRight', 'sidebarRightTabs', 'remote']

/**
 * Contribute the Source control tab to the right Sidebar and its rail button.
 * @param ctx - the browser plugin context.
 */
export function apply(ctx: ClientContext): void {
  ctx.effect(() => ctx.locale.register(NS, { zh, en }), 'ui-git: dictionaries')
  const t = ctx.locale.bind(NS)
  // Deployments built before this namespace entered their static Client assembly
  // do not mount it; mount our own generated contribution on first read. The
  // namespace is read through the service store because it is not in this
  // plugin's inject list.
  let mounting: Promise<void> | undefined
  const ensureRemote = async (): Promise<void> => {
    if (ctx.get('remote.git') !== undefined) return
    mounting ??= (async () => {
      try {
        await ctx.remote.$mount(gitRemote)
      } catch (error) {
        if (ctx.get('remote.git') === undefined) throw error
      } finally {
        mounting = undefined
      }
    })()
    await mounting
  }
  const gitService = (): ClientRemote['git'] => {
    const service: ClientRemote['git'] | undefined = ctx.get('remote.git')
    if (service === undefined) throw new Error('git: remote namespace is unavailable')
    return service
  }
  // The right column belongs to the Session on screen, which is the Conversation's
  // Session: this panel is global, so remembering the last one is what lets a file
  // click reach the column the Conversation draws.
  let lastSession = ctx.sidebarRight.mounted.getSnapshot()
  ctx.effect(() => ctx.sidebarRight.mounted.subscribe(() => {
    const current = ctx.sidebarRight.mounted.getSnapshot()
    if (current !== undefined) lastSession = current
  }), 'ui-git: on-screen session')

  const changeCount: ChangeCountSource = createChangeCountSource()
  const onlyWorkspace = (): WorkspaceId | undefined => {
    const items = ctx.workspaces.list.getSnapshot().items
    return items.length === 1 ? items[0]?.workspaceId : undefined
  }
  // Mounting the namespace during apply would race the page's boot, so the panel
  // triggers it: the first read mounts it, then the badge and the live watch
  // start once.
  let model: GitPanelModel
  let live: GitLive
  let warmed = false
  function refreshCount(): void {
    const workspaceId = model.getSnapshot().workspaceId ?? onlyWorkspace()
    if (workspaceId === undefined) return
    if (ctx.get('remote.git') === undefined) return
    void gitService().status(workspaceId).then((result) => {
      if (result.ok) changeCount.publish(result.value.entries.length)
    })
  }
  function syncLive(): void {
    live.follow(model.getSnapshot().workspaceId ?? onlyWorkspace())
  }
  const warm = async (): Promise<void> => {
    await ensureRemote()
    if (warmed) return
    warmed = true
    refreshCount()
    syncLive()
  }
  model = new GitPanelModel(async () => { await warm(); return gitService() }, changeCount)
  ctx.effect(() => () => { model.dispose() }, 'ui-git: panel model')
  // One Workspace is the only case where the badge's number is unambiguous
  // before the panel has read anything: it seeds here, and the panel keeps it
  // current from every status it settles while it is open.
  ctx.effect(() => {
    const off = ctx.workspaces.list.subscribe(() => { if (warmed) refreshCount() })
    return off
  }, 'ui-git: change count')
  // Live state: `.git` moves on a commit, a checkout, or an index write, and
  // nothing else tells the panel that its read went stale.
  live = createGitLive({
    watch: (workspaceId, signal) => ctx.remote.$stream<GitWatchFrame>({
      name: `repository ${workspaceId}`,
      open: () => gitService().watch(workspaceId, signal),
      ended: () => new Error(`Repository watch ended: ${workspaceId}`),
    }),
    onChange: () => {
      if (model.getSnapshot().workspaceId === undefined) refreshCount()
      else model.refresh()
    },
  })
  ctx.effect(() => {
    const off = ctx.workspaces.list.subscribe(() => { if (warmed) syncLive() })
    return () => { off(); live.dispose() }
  }, 'ui-git: live repository')

  /** Absolute path of one changed file, when a repository is located. */
  const absoluteOf = (path: string): string | undefined => {
    const root = model.getSnapshot().repository?.root
    if (root === undefined) return undefined
    return `${root.replace(/[/\\]+$/u, '')}/${path}`
  }
  /** Hand one file to the Editor panel; answers whether it was taken. */
  const openInEditor = (path: string): boolean => {
    const absolute = absoluteOf(path)
    return absolute !== undefined && ctx.get('editorNavigation')?.open(absolute) === true
  }
  /** Show one file in the right column's read-only preview, beside the conversation. */
  const openPreview = (path: string): void => {
    const absolute = absoluteOf(path)
    if (absolute === undefined) return
    const session = ctx.sidebarRight.mounted.getSnapshot() ?? lastSession
    if (session === undefined) return
    const address = fileAddressFor(session, undefined, absolute)
    ctx.sidebarRight.openResourceIn(session, address)
  }
  const injected = (): GitPanelInjected => ({
    hooks: { gitPanel: model, gitWorkspaces: ctx.workspaces.list },
    selectWorkspace: (workspaceId) => { model.selectWorkspace(workspaceId) },
    selectCommit: (oid) => { model.selectCommit(oid) },
    clearCommit: () => { model.clearCommit() },
    refresh: () => { model.refresh() },
    openFile: openPreview,
    openFileInEditor: (path) => { if (!openInEditor(path)) openPreview(path) },
  })

  ctx.effect(() => ctx.sidebarRightTabs.register(gitDefinition(t)), 'ui-git: git type')
  ctx.effect(() => ctx.slots.inject('sidebar.right.pane.tab', () => ctx.slots.register({
    name: 'sidebar.right.pane.tab',
    key: GIT_ID,
    locale: NS,
    inject: injected,
  }, GitPanel)), 'ui-git: git tab body')
  ctx.effect(() => ctx.slots.inject('sidebar.right.pane.tab.title', () => ctx.slots.register({
    name: 'sidebar.right.pane.tab.title',
    key: GIT_ID,
  }, GitTitle)), 'ui-git: git tab title')

  // The frame's right rail offers the same tool: it owns the button and the
  // toggle, and this registration contributes the glyph with the changed-file
  // count the panel publishes.
  ctx.slots.inject('rightrail', () => ctx.slots.register({
    name: 'rightrail',
    id: GIT_KIND,
    order: 20,
    label: () => t('panel'),
    locale: NS,
    inject: (): GitRailInjected => ({ hooks: { changeCount } }),
  }, GitRailIcon))
}
