/**
 * The Git tab body: one Workspace's repository in a narrow right-Sidebar panel.
 *
 * Two collapsible sections carry the surface — **Changes** as a directory tree
 * with git's status letters, and **Graph** as the history lanes with the refs
 * that point at each commit. The commit box is present but read-only: the Host
 * controller exposes no write operation yet, so stage, discard and commit are
 * deliberately not offered.
 *
 * The body draws only what its props carry: state through the hook the renderer
 * binds, selections and refresh through the injected face, and copy through the
 * dictionary.
 */
import { useEffect, useState } from 'react'
import type { ReactNode } from 'react'
import {
  IconBranchOutlineRegular, IconChevronDownOutlineRegular, IconChevronRightOutlineRegular,
  IconFolderCloseRegular, IconFolderOpenRegular, IconRefreshOutlineRegular, Tooltip,
} from '@deepseek-ai/dsh-client-ui-primitives'
import type { GitCommitView, GitStatusKind } from '@deepseek-ai/dsh-api-remotes/client'
import type { WorkspaceView } from '@deepseek-ai/dsh-api-workspace-controller/client'
import type { InjectFace, PropsLocale, PropsRuntime } from '@deepseek-ai/dsh-client-ui-slots'
import { assignLanes } from './lanes.ts'
import type { GraphRow } from './lanes.ts'
import type { GitPanelInjected } from './slots.ts'
import { buildChangeTree } from './tree.ts'
import type { ChangeNode } from './tree.ts'
import css from './GitPanel.module.css'

/** Full component props assembled by the tab renderer. */
export type GitPanelProps =
  PropsRuntime<'sidebar.right.pane.tab'>
  & PropsLocale<'git'>
  & InjectFace<GitPanelInjected>

/** git's own status letter for one side of a change; a space means no change. */
const STATUS_LETTER: Record<GitStatusKind, string> = {
  unmodified: ' ',
  modified: 'M',
  added: 'A',
  deleted: 'D',
  renamed: 'R',
  copied: 'C',
  typechange: 'T',
  unmerged: 'U',
  untracked: '?',
}

/** Lane column width in pixels; the stylesheet and the gutter agree on it. */
const LANE_STEP = 12

/** Ref pills one history row draws before it counts the rest. */
const REF_PILLS = 2

/**
 * One status letter.
 * @param props - the state this side of the change holds.
 * @returns the letter chip.
 */
function Letter({ kind }: { readonly kind: GitStatusKind }): ReactNode {
  return <span className={css.letter} data-kind={kind} aria-hidden="true">{STATUS_LETTER[kind]}</span>
}

/**
 * The graph gutter: the rails carried through this row and the commit's dot.
 * @param props - one history row's geometry.
 * @returns the gutter drawing.
 */
function Gutter({ row }: { readonly row: GraphRow }): ReactNode {
  const columns = row.rails.reduce((widest, rail) => Math.max(widest, rail.lane + 1), row.lane + 1)
  const width = columns * LANE_STEP
  const centre = (lane: number): number => lane * LANE_STEP + LANE_STEP / 2
  return (
    <svg className={css.gutter} width={width} height={22} viewBox={`0 0 ${String(width)} 22`} aria-hidden="true">
      {row.rails.map(rail => (
        <line
          key={rail.lane}
          className={css.rail}
          data-color={rail.color}
          x1={centre(rail.lane)}
          x2={centre(rail.lane)}
          y1={rail.from}
          y2={rail.to}
        />
      ))}
      <circle className={css.dot} data-color={row.color} cx={centre(row.lane)} cy={11} r={3.5} />
    </svg>
  )
}

/**
 * One changed path or one collapsed directory of them.
 * @param props - the node, the collapsed set, its toggler, and the open callback.
 * @returns the row and, for an expanded directory, its children.
 */
function ChangeNodeRow({ node, expanded, onToggle, onOpen, onOpenInEditor }: {
  readonly node: ChangeNode
  readonly expanded: ReadonlySet<string>
  readonly onToggle: (path: string) => void
  readonly onOpen: (path: string) => void
  readonly onOpenInEditor: (path: string) => void
}): ReactNode {
  if (node.entry !== undefined) {
    return (
      <li>
        <button
          type="button"
          className={css.rowButton}
          title={node.entry.from === undefined ? node.entry.path : `${node.entry.path} ← ${node.entry.from}`}
          onClick={() => { onOpen(node.entry?.path ?? node.path) }}
          onDoubleClick={() => { onOpenInEditor(node.entry?.path ?? node.path) }}
        >
          <Letter kind={node.kind} />
          <span className={css.fileName}>{node.name}</span>
        </button>
      </li>
    )
  }
  const isExpanded = expanded.has(node.path)
  return (
    <li>
      <button type="button" className={css.rowButton} aria-expanded={isExpanded} onClick={() => { onToggle(node.path) }}>
        {isExpanded
          ? <IconChevronDownOutlineRegular size={13} className={css.chevron} />
          : <IconChevronRightOutlineRegular size={13} className={css.chevron} />}
        {isExpanded
          ? <IconFolderOpenRegular size={14} className={css.folderIcon} />
          : <IconFolderCloseRegular size={14} className={css.folderIcon} />}
        <span className={css.dirName}>{node.name}</span>
        <span className={css.folderDot} data-kind={node.kind} aria-hidden="true" />
      </button>
      {isExpanded && (
        <ul className={css.tree}>
          {node.children.map(child => (
            <ChangeNodeRow
              key={child.path}
              node={child}
              expanded={expanded}
              onToggle={onToggle}
              onOpen={onOpen}
              onOpenInEditor={onOpenInEditor}
            />
          ))}
        </ul>
      )}
    </li>
  )
}

/**
 * One history row.
 * @param props - the row's geometry, its selection, and the selection callback.
 * @returns the row.
 */
function CommitRow({ row, selected, onSelect }: {
  readonly row: GraphRow
  readonly selected: boolean
  readonly onSelect: (oid: string) => void
}): ReactNode {
  const commit: GitCommitView = row.commit
  const extra = commit.refs.length - REF_PILLS
  return (
    <li className={css.commitRow} data-selected={selected}>
      <button type="button" className={css.commitButton} onClick={() => { onSelect(commit.oid) }}>
        <Gutter row={row} />
        <span className={css.commitText}>
          <span className={css.subject}>{commit.subject}</span>
          {commit.refs.length > 0 && (
            <span className={css.pills}>
              {commit.refs.slice(0, REF_PILLS).map(ref => <span key={ref} className={css.pill}>{ref}</span>)}
              {extra > 0 && <span className={css.pill}>{'+'}{String(extra)}</span>}
            </span>
          )}
        </span>
      </button>
    </li>
  )
}

/**
 * One collapsible section of the panel.
 * @param props - the section's label, count, open state, toggler, and children.
 * @returns the section.
 */
function Section({ label, count, open, onToggle, children }: {
  readonly label: string
  readonly count: number
  readonly open: boolean
  readonly onToggle: () => void
  readonly children: ReactNode
}): ReactNode {
  return (
    <section className={css.section}>
      <button type="button" className={css.sectionToggle} aria-expanded={open} onClick={onToggle}>
        {open ? <IconChevronDownOutlineRegular size={14} /> : <IconChevronRightOutlineRegular size={14} />}
        <span className={css.sectionTitle}>{label}</span>
        {count > 0 && <span className={css.count}>{count}</span>}
      </button>
      {open && <div className={css.sectionBody}>{children}</div>}
    </section>
  )
}

/**
 * Render the Git panel.
 * @param props - the tab runtime currency, the panel's injected face, and the translator.
 * @returns the panel element.
 */
export function GitPanel({
  useGitPanel, useGitWorkspaces, selectWorkspace, selectCommit, openFile, openFileInEditor, refresh, t,
}: GitPanelProps): ReactNode {
  const state = useGitPanel(snapshot => snapshot)
  const workspaces = useGitWorkspaces(snapshot => snapshot.items)
  const [changesOpen, setChangesOpen] = useState(true)
  const [graphOpen, setGraphOpen] = useState(true)
  const [expanded, setExpanded] = useState<ReadonlySet<string>>(() => new Set())
  useEffect(() => {
    if (state.workspaceId !== undefined) return
    const first: WorkspaceView | undefined = workspaces[0]
    if (first === undefined) return
    selectWorkspace(first.workspaceId)
  }, [state.workspaceId, workspaces, selectWorkspace])

  const repository = state.repository
  const entries = state.status?.entries ?? []
  const branch = repository === undefined
    ? ''
    : repository.head.kind === 'branch' || repository.head.kind === 'unborn'
      ? repository.head.branch
      : t('detached')
  const rows = assignLanes(state.commits)
  const ready = state.failure === undefined && repository !== undefined

  const toggleNode = (path: string): void => {
    setExpanded((previous) => {
      const next = new Set(previous)
      if (next.has(path)) next.delete(path)
      else next.add(path)
      return next
    })
  }

  return (
    <div className={css.panel}>
      <header className={css.head}>
        <span className={css.identity}>
          <IconBranchOutlineRegular size={14} />
          <span className={css.branch}>{branch}</span>
          {repository?.upstream !== undefined && (
            <span className={css.mono}>{'+'}{String(repository.upstream.ahead)}{' -'}{String(repository.upstream.behind)}</span>
          )}
          {repository !== undefined && <span className={css.repoName}>{repository.name}</span>}
        </span>
        <span className={css.tools}>
          {workspaces.length > 1 && workspaces.map(workspace => (
            <button
              key={workspace.workspaceId}
              type="button"
              className={css.workspaceButton}
              data-active={workspace.workspaceId === state.workspaceId}
              onClick={() => { selectWorkspace(workspace.workspaceId) }}
            >
              {workspace.title}
            </button>
          ))}
          <Tooltip label={t('refresh')}>
            <button type="button" className={css.iconButton} aria-label={t('refresh')} onClick={() => { refresh() }}>
              <IconRefreshOutlineRegular size={14} />
            </button>
          </Tooltip>
        </span>
      </header>

      {state.failure !== undefined && (
        <p className={css.notice}>
          {state.failure.code === 'git/unavailable' ? t('unavailable') : t('failed')}
        </p>
      )}
      {state.failure === undefined && state.workspaceId === undefined && <p className={css.notice}>{t('noWorkspace')}</p>}
      {state.failure === undefined && state.workspaceId !== undefined && state.phase === 'loading'
        && repository === undefined && <p className={css.notice}>{t('loading')}</p>}
      {state.failure === undefined && state.notARepository && <p className={css.notice}>{t('notARepository')}</p>}

      {ready && (
        <>
          <div className={css.scroll}>
            <Section
              label={t('changes')}
              count={entries.length}
              open={changesOpen}
              onToggle={() => { setChangesOpen(!changesOpen) }}
            >
              {entries.length === 0
                ? <p className={css.note}>{t('noChanges')}</p>
                : (
                  <ul className={css.tree}>
                    {buildChangeTree(entries).map(node => (
                      <ChangeNodeRow
                        key={node.path}
                        node={node}
                        expanded={expanded}
                        onToggle={toggleNode}
                        onOpen={openFile}
                        onOpenInEditor={openFileInEditor}
                      />
                    ))}
                  </ul>
                )}
            </Section>
            <Section
              label={t('graph')}
              count={state.commits.length}
              open={graphOpen}
              onToggle={() => { setGraphOpen(!graphOpen) }}
            >
              {state.commits.length === 0
                ? <p className={css.note}>{t('noCommits')}</p>
                : (
                  <ul className={css.graph}>
                    {rows.map(row => (
                      <CommitRow
                        key={row.commit.oid}
                        row={row}
                        selected={row.commit.oid === state.selected}
                        onSelect={selectCommit}
                      />
                    ))}
                  </ul>
                )}
              {state.more && <p className={css.note}>{t('moreCommits')}</p>}
            </Section>
          </div>
          <div className={css.commitBox}>
            <textarea
              className={css.textarea}
              rows={2}
              disabled
              placeholder={t('commitPlaceholder')}
              aria-label={t('commitPlaceholder')}
            />
            <button type="button" className={css.commitAction} disabled>{t('commit')}</button>
          </div>
        </>
      )}
    </div>
  )
}
