/**
 * The changed paths folded into a directory tree, so a narrow panel keeps long
 * paths readable instead of clipping their file name.
 *
 * A directory carries the strongest status among its descendants, which is what
 * its collapsed row dots.
 */
import type { GitStatusEntry, GitStatusKind } from '@deepseek-ai/dsh-api-remotes/client'

/** One directory or one changed file in the tree. */
export interface ChangeNode {
  /** Path relative to the repository root. */
  readonly path: string
  /** Last path segment, what the row draws. */
  readonly name: string
  readonly children: readonly ChangeNode[]
  /** The changed file this node is; absent for a directory. */
  readonly entry?: GitStatusEntry
  /** This node's status: the file's own, or the strongest among its descendants. */
  readonly kind: GitStatusKind
}

/** Mutable builder node; converted once the whole tree exists. */
interface Builder {
  readonly path: string
  readonly name: string
  readonly children: Map<string, Builder>
  entry?: GitStatusEntry
}

/** How strongly each status paints a row; the strongest descendant wins. */
const SEVERITY: Record<GitStatusKind, number> = {
  unmodified: 0,
  untracked: 1,
  added: 1,
  copied: 2,
  renamed: 3,
  typechange: 4,
  modified: 5,
  deleted: 6,
  unmerged: 7,
}

/**
 * The side of a change a file row reports: the working tree wins over the index.
 * @param entry - one changed path with its two sides.
 * @returns the status the row draws.
 */
export function dominantKind(entry: GitStatusEntry): GitStatusKind {
  if (entry.worktree !== 'unmodified' && entry.worktree !== 'untracked') return entry.worktree
  if (entry.index !== 'unmodified') return entry.index
  return entry.worktree
}

/** Directories first, then case-insensitive natural name order. */
const byName = (left: Builder, right: Builder): number => {
  const leftDir = left.children.size > 0
  const rightDir = right.children.size > 0
  if (leftDir !== rightDir) return leftDir ? -1 : 1
  return left.name.localeCompare(right.name, undefined, { numeric: true, sensitivity: 'base' })
}

/**
 * Build the nested changes tree from git's changed-path list.
 * @param entries - paths relative to the repository root, in git's order.
 * @returns the root level, directories before files.
 */
export function buildChangeTree(entries: readonly GitStatusEntry[]): readonly ChangeNode[] {
  const root: Builder = { path: '', name: '', children: new Map() }
  for (const entry of entries) {
    const segments = entry.path.split('/')
    let node = root
    let path = ''
    for (const [index, segment] of segments.entries()) {
      path = path === '' ? segment : `${path}/${segment}`
      let child = node.children.get(segment)
      if (child === undefined) {
        child = { path, name: segment, children: new Map() }
        node.children.set(segment, child)
      }
      if (index === segments.length - 1) child.entry = entry
      node = child
    }
  }
  const convert = (nodes: Iterable<Builder>): ChangeNode[] =>
    [...nodes].sort(byName).map((node) => {
      const children = convert(node.children.values())
      const own: GitStatusKind = node.entry === undefined ? 'unmodified' : dominantKind(node.entry)
      const kind = children.reduce<GitStatusKind>(
        (current, child) => (SEVERITY[child.kind] > SEVERITY[current] ? child.kind : current),
        own,
      )
      return {
        path: node.path,
        name: node.name,
        children,
        kind,
        ...(node.entry === undefined ? {} : { entry: node.entry }),
      }
    })
  return convert(root.children.values())
}
